        LinearLayout wrap=column();wrap.setGravity(Gravity.CENTER);pad(wrap,34,28);body.addView(wrap,new LinearLayout.LayoutParams(-1,-1));Ui.Icon note=icon("note",Ui.accent,null);wrap.addView(note,lp(100,100));space(wrap,24);TextView heading=title("Your music.\nYour moment.",36);heading.setGravity(Gravity.CENTER);wrap.addView(heading);space(wrap,16);TextView info=text("All the songs on your phone, together in one place. Offline, uninterrupted.",16,Ui.muted);info.setGravity(Gravity.CENTER);info.setLineSpacing(d(5),1);wrap.addView(info);space(wrap,36);wrap.addView(button("Find my music",this::requestMusic),lp(-1,54));space(wrap,12);TextView detail=text("Allow audio access to find and play your files.",12,Ui.muted);detail.setGravity(Gravity.CENTER);wrap.addView(detail);TextView appSettings=text("Open app permissions",14,Ui.accent);pad(appSettings,12,16);appSettings.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));wrap.addView(appSettings);
