        section(l,"ABOUT");setting(l,"Music","Version 1.0 · Local music player","note",()->new AlertDialog.Builder(this).setTitle("Music 1.0").setMessage("An independent music player inspired by Mi Music.\n\nPlays audio stored on your phone. No ads, accounts, analytics or streaming. No internet permission.\n\nAudio support depends on your phone’s codecs, including common MP3, AAC, FLAC, OGG, WAV and M4A files.\n\nNot affiliated with Xiaomi.").setPositiveButton("Got it",null).show());setting(l,"App permissions","Manage audio access and notifications","settings",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));setting(l,"Clear listening history","Keeps your music and playlists","clock",()->new AlertDialog.Builder(this).setTitle("Clear listening history?").setMessage("Recently played songs will be removed from your history.").setPositiveButton("Clear",(a,b)->{library.prefs().edit().remove("recent").apply();toast("History cleared");}).setNegativeButton("Cancel",null).show());space(l,20);
