    private void section(LinearLayout l,String title){TextView t=text(title,11,Ui.accent);t.setLetterSpacing(.12f);Ui.bold(t);LinearLayout.LayoutParams p=lp(-1,48);p.topMargin=d(12);l.addView(t,p);}
    private void setting(LinearLayout l,String name,String subtitle,String glyph,Runnable action){l.addView(groupRow(name,subtitle,glyph,action));}
    private void toggle(LinearLayout l,String name,String subtitle,String key,boolean defaultValue){LinearLayout r=row();pad(r,8,14);LinearLayout labels=column();TextView t=title(name,15);labels.addView(t);TextView sub=text(subtitle,12,Ui.muted);sub.setMaxLines(2);labels.addView(sub,lp(-1,42));r.addView(labels,new LinearLayout.LayoutParams(0,-2,1));Switch s=new Switch(this);s.setContentDescription(name);s.setChecked(library.prefs().getBoolean(key,defaultValue));s.setOnCheckedChangeListener((v,value)->library.prefs().edit().putBoolean(key,value).apply());r.addView(s);l.addView(r);}
    private interface StringResult{void accept(String value);}
    private void choice(String title,String[] values,String current,StringResult result){new AlertDialog.Builder(this).setTitle(title).setSingleChoiceItems(values,Arrays.asList(values).indexOf(current),(dialog,which)->{dialog.dismiss();result.accept(values[which]);}).setNegativeButton("Cancel",null).show();}
    private void filterDialog(){LinearLayout l=column();pad(l,24,8);l.addView(text("Minimum song length (seconds)",14,Ui.ink));EditText duration=new EditText(this);duration.setInputType(2);duration.setText(""+library.prefs().getInt("minDuration",0));l.addView(duration);space(l,14);l.addView(text("Minimum file size (KB)",14,Ui.ink));EditText size=new EditText(this);size.setInputType(2);size.setText(""+library.prefs().getInt("minSize",0));l.addView(size);space(l,8);l.addView(text("Set both to 0 to include every audio file.",12,Ui.muted));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Filter audio files").setView(l).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{int sec=Integer.parseInt(duration.getText().toString()),kb=Integer.parseInt(size.getText().toString());if(sec<0||kb<0)throw new NumberFormatException();library.prefs().edit().putInt("minDuration",sec).putInt("minSize",kb).apply();dialog.dismiss();scan();}catch(NumberFormatException e){toast("Enter a valid non-negative number");}}));dialog.show();}
    private void folderDialog(){Set<String> names=new TreeSet<>();for(Song s:songs)names.add(s.folder);Set<String> excluded=new HashSet<>(library.prefs().getStringSet("excluded",Collections.emptySet()));names.addAll(excluded);String[] values=names.toArray(new String[0]);if(values.length==0){toast("Scan your phone first");return;}boolean[] checked=new boolean[values.length];for(int i=0;i<values.length;i++)checked[i]=excluded.contains(values[i]);new AlertDialog.Builder(this).setTitle("Exclude folders").setMultiChoiceItems(values,checked,(dialog,which,on)->{if(on)excluded.add(values[which]);else excluded.remove(values[which]);}).setPositiveButton("Save",(a,b)->{library.prefs().edit().putStringSet("excluded",excluded).apply();scan();}).setNegativeButton("Cancel",null).show();}
    private void speedDialog(){if(service==null)return;String[] values={"0.5×","0.75×","1.0×","1.25×","1.5×","1.75×","2.0×"};choice("Playback speed",values,service.speed()+"×",s->{service.setSpeed(Float.parseFloat(s.replace("×","")));if(page.equals("settings"))render();});}
    private void sleepDialog(){if(service==null)return;String[] choices={"Off","15 minutes","30 minutes","45 minutes","60 minutes","Custom…"};new AlertDialog.Builder(this).setTitle("Sleep timer").setItems(choices,(a,b)->{if(b==5){EditText n=new EditText(this);n.setInputType(2);n.setHint("Minutes (1–1440)");pad(n,24,12);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Stop playback after").setView(n).setPositiveButton("Set timer",null).setNegativeButton("Cancel",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(w->{try{int minutes=Integer.parseInt(n.getText().toString());if(minutes<1||minutes>1440)throw new NumberFormatException();service.sleep(minutes);dlg.dismiss();updatePlayback();if(page.equals("settings"))render();}catch(Exception e){n.setError("Enter 1–1440 minutes");}}));dlg.show();}else{service.sleep(b==0?0:b*15);updatePlayback();if(page.equals("settings"))render();toast(b==0?"Sleep timer off":"Playback will stop in "+b*15+" minutes");}}).setNegativeButton("Cancel",null).show();}
    private void equalizerDialog(){
        if(service==null||service.equalizer()==null){toast("Play a song to adjust the equalizer");return;}Equalizer eq=service.equalizer();LinearLayout l=column();pad(l,24,8);Switch enable=new Switch(this);enable.setText("Enable equalizer");enable.setTextColor(Ui.ink);enable.setChecked(library.prefs().getBoolean("eqEnabled",false));enable.setOnCheckedChangeListener((v,b)->{library.prefs().edit().putBoolean("eqEnabled",b).apply();service.applyEqualizer();});l.addView(enable,lp(-1,52));short[] range=eq.getBandLevelRange();short count=eq.getNumberOfBands();TextView preset=text("Choose preset",14,Ui.accent);pad(preset,0,14);l.addView(preset);LinearLayout sliders=column();l.addView(sliders);
        Runnable renderBands=()->{sliders.removeAllViews();for(short i=0;i<count;i++){final short band=i;int frequency=eq.getCenterFreq(i)/1000;TextView label=text((frequency>=1000?String.format(Locale.US,"%.1f kHz",frequency/1000f):frequency+" Hz")+"   ·   "+library.prefs().getInt("eq"+i,0)/100f+" dB",12,Ui.muted);sliders.addView(label);SeekBar bar=new SeekBar(this);bar.setContentDescription("Equalizer "+frequency+" Hz");bar.setMax(range[1]-range[0]);bar.setProgress(library.prefs().getInt("eq"+i,0)-range[0]);sliders.addView(bar,lp(-1,40));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){if(user){int level=p+range[0];library.prefs().edit().putInt("eq"+band,level).apply();service.applyEqualizer();label.setText((frequency>=1000?String.format(Locale.US,"%.1f kHz",frequency/1000f):frequency+" Hz")+"   ·   "+level/100f+" dB");}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});}};
        renderBands.run();preset.setOnClickListener(v->{List<String> names=new ArrayList<>();names.add("Flat");for(short i=0;i<eq.getNumberOfPresets();i++)names.add(eq.getPresetName(i));new AlertDialog.Builder(this).setTitle("Equalizer preset").setItems(names.toArray(new String[0]),(dialog,which)->{if(which>0)eq.usePreset((short)(which-1));android.content.SharedPreferences.Editor edit=library.prefs().edit();for(short i=0;i<count;i++)edit.putInt("eq"+i,which==0?0:eq.getBandLevel(i));edit.apply();service.applyEqualizer();preset.setText(names.get(which));renderBands.run();}).show();});ScrollView scroll=new ScrollView(this);scroll.addView(l);new AlertDialog.Builder(this).setTitle("Equalizer").setView(scroll).setPositiveButton("Done",null).show();
    }
    private void scan(){if(scanning||!hasPermission())return;scanning=true;toast("Scanning for music…");worker.execute(()->{try{List<Song> found=library.scan(this);handler.post(()->{scanning=false;if(isDestroyed())return;songs=found;if(page.equals("library"))refreshLibraryContent();else if(page.equals("collection")||page.equals("settings"))render();toast("Found "+songs.size()+" songs");});}catch(Exception e){handler.post(()->{scanning=false;toast("Couldn't read audio files. Check music access in app permissions.");});}});}
    private void newPlaylist(Song add){inputDialog("New playlist","Playlist name","",name->{if(library.playlistNames().contains(name)){toast("A playlist with that name already exists");return;}library.createPlaylist(name);if(add!=null)library.addToPlaylist(name,add);toast("Playlist created");if(page.equals("library"))refreshLibraryContent();});}
    private void inputDialog(String title,String hint,String value,StringResult result){EditText input=new EditText(this);input.setSingleLine();input.setHint(hint);input.setText(value);pad(input,24,12);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(title).setView(input).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(w->{String s=input.getText().toString().trim();if(s.isEmpty()){input.setError("Enter a name");return;}if(s.length()>100){input.setError("Use 100 characters or fewer");return;}dlg.dismiss();result.accept(s);}));dlg.show();}
    private void playlistOptions(String name){new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"Rename playlist","Delete playlist"},(dialog,which)->{if(which==0)inputDialog("Rename playlist","Playlist name",name,newName->{if(library.playlistNames().contains(newName)&&!newName.equals(name)){toast("A playlist with that name already exists");return;}library.renamePlaylist(name,newName);if(page.equals("collection"))group=newName;render();});else new AlertDialog.Builder(this).setTitle("Delete playlist?").setMessage("Your music files will stay on your phone.").setPositiveButton("Delete",(a,b)->{library.deletePlaylist(name);route("library");}).setNegativeButton("Cancel",null).show();}).show();}
    private void addToPlaylist(Song s){List<String> names=library.playlistNames();names.add(0,"+ New playlist");new AlertDialog.Builder(this).setTitle("Add to playlist").setItems(names.toArray(new String[0]),(a,b)->{if(b==0)newPlaylist(s);else{library.addToPlaylist(names.get(b),s);toast("Added to "+names.get(b));}}).show();}
    private void songOptions(Song s){if(s==null)return;List<String> values=new ArrayList<>(Arrays.asList("Play next","Add to queue",library.favorite(s)?"Remove from favourites":"Add to favourites","Add to playlist","Share audio file","Song information"));if(page.equals("collection")&&category.equals("playlist"))values.add("Remove from playlist");new AlertDialog.Builder(this).setTitle(s.title).setItems(values.toArray(new String[0]),(dialog,which)->{switch(which){case 0:if(service!=null)service.enqueue(s,true);toast("Playing next");break;case 1:if(service!=null)service.enqueue(s,false);toast("Added to queue");break;case 2:library.toggleFavorite(s);updatePlayback();if(page.equals("collection")&&category.equals("favorites"))render();break;case 3:addToPlaylist(s);break;case 4:Intent share=new Intent(Intent.ACTION_SEND).setType("audio/*").putExtra(Intent.EXTRA_STREAM,s.uri()).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);share.setClipData(ClipData.newRawUri(s.title,s.uri()));try{startActivity(Intent.createChooser(share,"Share song"));}catch(Exception e){toast("No app available to share this file");}break;case 5:new AlertDialog.Builder(this).setTitle("Song information").setMessage(s.title+"\n\nArtist: "+s.artist+"\nAlbum: "+s.album+"\nDuration: "+Song.time(s.duration)+"\nSize: "+String.format(Locale.US,"%.2f MB",s.size/1048576f)+"\n\n"+s.path).setPositiveButton("Done",null).show();break;case 6:library.removeFromPlaylist(group,s);render();break;}}).show();}
    private void queue(){header("Playing queue",null,"");if(service==null||service.queue.isEmpty()){empty(body,"Your queue is empty","Choose a song from your library to start listening.");return;}LinearLayout controls=row();pad(controls,24,0);controls.addView(text(service.queue.size()+" songs",13,Ui.muted),new LinearLayout.LayoutParams(0,d(44),1));TextView help=text("Tap to play · Hold for options",11,Ui.muted);controls.addView(help);body.addView(controls);ListView list=new ListView(this);list.setDivider(null);list.setPadding(d(16),0,d(16),0);adapter=new SongAdapter(new ArrayList<>(service.queue));list.setAdapter(adapter);list.setOnItemClickListener((a,b,which,id)->{service.jump(which);updatePlayback();if(adapter!=null)adapter.notifyDataSetChanged();});list.setOnItemLongClickListener((a,b,which,id)->{new AlertDialog.Builder(this).setTitle(service.queue.get(which).title).setItems(new String[]{"Move up","Move down","Remove from queue"},(dlg,option)->{if(option==0)service.moveQueue(which,which-1);else if(option==1)service.moveQueue(which,which+1);else service.removeQueue(which);render();}).show();return true;});body.addView(list,new LinearLayout.LayoutParams(-1,0,1));}
    private long lyricsSongId=-1;
    private void lyricsDialog(){if(service==null||service.current()==null){toast("Choose a song first");return;}Song s=service.current();String saved=library.prefs().getString("lyrics"+s.id,"");if(saved.isEmpty()){new AlertDialog.Builder(this).setTitle("Lyrics").setMessage("Add a .lrc or .txt file from your phone. Lyrics stay on this device.").setPositiveButton("Choose lyrics file",(a,b)->pickLyrics(s)).setNegativeButton("Cancel",null).show();return;}
        TextView words=text("",17,Ui.ink);words.setGravity(Gravity.CENTER);pad(words,24,20);words.setLineSpacing(d(12),1);ScrollView scroll=new ScrollView(this);scroll.addView(words);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(s.title).setView(scroll).setPositiveButton("Done",null).setNeutralButton("Replace file",(a,b)->pickLyrics(s)).setNegativeButton("Remove",(a,b)->library.prefs().edit().remove("lyrics"+s.id).apply()).create();
        java.util.regex.Pattern pattern=java.util.regex.Pattern.compile("\\[(\\d+):(\\d{1,2})(?:[.:](\\d{1,3}))?\\]");TreeMap<Long,String> timed=new TreeMap<>();for(String line:saved.split("\n")){java.util.regex.Matcher m=pattern.matcher(line);List<Long> stamps=new ArrayList<>();while(m.find()){String frac=m.group(3);long ms=frac==null?0:Long.parseLong((frac+"000").substring(0,3));stamps.add(Long.parseLong(m.group(1))*60000+Long.parseLong(m.group(2))*1000+ms);}String lyric=pattern.matcher(line).replaceAll("").trim();for(long stamp:stamps)timed.put(stamp,lyric);}if(timed.isEmpty())words.setText(saved);else{Runnable sync=new Runnable(){public void run(){if(!dlg.isShowing()||isDestroyed())return;long pos=service!=null&&service.current()!=null&&service.current().id==s.id?service.position():0;Long current=timed.floorKey(pos);android.text.SpannableStringBuilder styled=new android.text.SpannableStringBuilder();int focusOffset=0;for(Map.Entry<Long,String> e:timed.entrySet()){int start=styled.length();styled.append(e.getValue()).append("\n");styled.setSpan(new android.text.style.ForegroundColorSpan(e.getKey().equals(current)?Ui.accent:Ui.muted),start,styled.length(),33);if(e.getKey().equals(current))focusOffset=start;}words.setText(styled);final int offset=focusOffset;words.post(()->{if(words.getLayout()!=null)scroll.smoothScrollTo(0,Math.max(0,words.getLayout().getLineTop(words.getLayout().getLineForOffset(Math.min(offset,words.length())))-scroll.getHeight()/3));});handler.postDelayed(this,700);}};dlg.setOnShowListener(v->handler.post(sync));}dlg.show();
    }
    private void pickLyrics(Song s){lyricsSongId=s.id;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,40);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==40&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();long id=lyricsSongId;worker.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] chunk=new byte[4096];int n;while((n=in.read(chunk))!=-1){if(bytes.size()+n>512*1024)throw new IOException("Too large");bytes.write(chunk,0,n);}String content=bytes.toString("UTF-8");library.prefs().edit().putString("lyrics"+id,content).apply();handler.post(()->{toast("Lyrics added");if(service!=null&&service.current()!=null&&service.current().id==id)lyricsDialog();});}catch(Exception e){handler.post(()->toast("Couldn't read lyrics. Choose a UTF-8 text or LRC file under 512 KB."));}});}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
